   if(feat.obstacle==='mines')for(let k=0;k<14;k++){const pos=add(add(add(S,mul(so.f,2600+r()*5200)),mul(so.r,(r()-.5)*3400)),mul(so.u,(r()-.5)*2400));const m=spawn('mine',pos,{speed:0,clean:false});m.hazard=true;}
