 // ---------------- TEST MODE (grown-ups: Ctrl+Shift+G + passphrase) — a practice copy where anything goes ----------------
 let testTab='scen',testMsg='';
 function snapReal(){const realMode=mode;if(mode==='flight'&&P&&planet)C.flight={sys:C.sys,pos:P.pos.slice(),o:{r:P.o.r.slice(),u:P.o.u.slice(),f:P.o.f.slice()},speed:P.speed,throttle:P.throttle,shF:P.shF,shA:P.shA,energy:P.energy};return{C:JSON.stringify(C),mode:realMode==='flight'?'flight':'docked',tab,menu:overlay==='menu'?menuTab:null};}
