 function testExit(){if(!test)return;const r=test.real;test=null;restoreReal(r);msg('TEST MODE OFF — BACK TO YOUR GAME',3,'#3cff6a');}
 const tGal=gx=>{C.gx=gx;GAL=SL.makeGalaxy(GSEED+gx*1009,COUNT);nbr=null;pregenFor=null;};
 function tDock(sys){if(sys!==undefined){C.sys=sys;C.visited[sys]=1;}scene=null;dockComp=false;jump=false;timeScale=1;race=null;ships=[];overlay=null;seat=null;mode='docked';tab='status';C.flight=null;}
 function tFly(){if(mode!=='flight'){if(mode!=='docked')tDock();launch();scene=null;mode='flight';anim=0;bootT=0;try{P.pos=tOpenSpace(22000);faceClear();P.speed=160;P.throttle=.4;}catch(e){}}overlay=null;G._departing=false;return P;}
 const tAhead=(d,side=0,up=0)=>add(add(add(P.pos,mul(P.o.f,d)),mul(P.o.r,side)),mul(P.o.u,up));
 const tClear=()=>ships.forEach(x=>{if(x!==station)x.dead=true;});
 const tFoe=(type,d,side,up)=>{const sh=spawn(type,tAhead(d,side,up),{});sh.angry=true;sh.target='player';return sh;};
 function tNear(){const cur=GAL[C.sys];return GAL.filter(g=>g.i!==C.sys&&SL.dist(cur,g)<=7).sort((a,b)=>SL.dist(cur,a)-SL.dist(cur,b));}
 function tSysWith(fn){return GAL.find(g=>g.i!==C.sys&&fn(g));}
