 const advSafe=p=>{for(const b of[planet,...moons,...suns]){if(!b||!b.pos)continue;const R=(b.R||0)*(suns.includes(b)?2.2:1.5)+400,d=sub(p,b.pos),l=len(d);if(l<R)p=add(b.pos,mul(l>1?mul(d,1/l):V(0,1,0),R));}return p;};
