  let y2=96;y2=sec(282,y2,`🦸 FAME — ${fameT(hero)}`,[['Hero points',n(hero)],['Pirates destroyed',n(S.k_pirate)],['Vorn aliens destroyed',n(S.k_alien)],['Mines and rocks cleared',n((S.k_mine||0)+(S.k_rock||0))]],'#3cff6a');
